const items = $input.all();
const first = items[0].json;

const data = first.body || first;

if (!data.text) {
  return [{ json: { error: 'Campo text no encontrado', received: JSON.stringify(first) } }];
}

const words = data.text.split(' ');
const chunkSize = 500;
const chunks = [];
let current = [];
let currentLen = 0;
let chunkNum = 1;

for (const word of words) {
  current.push(word);
  currentLen += word.length + 1;
  if (currentLen >= chunkSize) {
    chunks.push({
      document_id: data.document_id,
      filename: data.filename,
      chunk_number: chunkNum,
      text: current.join(' ')
    });
    current = [];
    currentLen = 0;
    chunkNum++;
  }
}
if (current.length > 0) {
  chunks.push({
    document_id: data.document_id,
    filename: data.filename,
    chunk_number: chunkNum,
    text: current.join(' ')
  });
}

return [{ json: { chunks: chunks } }];
